// Helper to create valid InstanceId
fn iid(s: &str) -> InstanceId {
    InstanceId::parse(s).unwrap()
}

fn default_iid() -> InstanceId {
    iid("01H5JYV4XHGSR2F8KZ9BWNRFMA")
}

