mod bdd_lifecycle_fsm {
    use super::*;

    // --- Claim: Pending → Running is the only happy-path start ---
    #[test]
    fn given_pending_when_start_then_running() {
        let next = compute_next_state(ActorLifecycleState::Pending, LifecycleTransition::Start);
        assert_eq!(next, Some(ActorLifecycleState::Running));
    }

    // --- Claim: Pending can fail directly ---
    #[test]
    fn given_pending_when_fail_then_failed() {
        let next = compute_next_state(ActorLifecycleState::Pending, LifecycleTransition::Fail);
        assert_eq!(next, Some(ActorLifecycleState::Failed));
    }

    // --- Claim: Running → Stopping on Stop ---
    #[test]
    fn given_running_when_stop_then_stopping() {
        let next = compute_next_state(ActorLifecycleState::Running, LifecycleTransition::Stop);
        assert_eq!(next, Some(ActorLifecycleState::Stopping));
    }

    // --- Claim: Running can fail directly ---
    #[test]
    fn given_running_when_fail_then_failed() {
        let next = compute_next_state(ActorLifecycleState::Running, LifecycleTransition::Fail);
        assert_eq!(next, Some(ActorLifecycleState::Failed));
    }

    // --- Claim: Stopping → Stopping on ChildStopped (waits for siblings) ---
    #[test]
    fn given_stopping_when_child_stopped_then_still_stopping() {
        let next = compute_next_state(
            ActorLifecycleState::Stopping,
            LifecycleTransition::ChildStopped,
        );
        assert_eq!(next, Some(ActorLifecycleState::Stopping));
    }

    // --- Claim: Stopping → Stopped only when all children done ---
    #[test]
    fn given_stopping_when_all_children_stopped_then_stopped() {
        let next = compute_next_state(
            ActorLifecycleState::Stopping,
            LifecycleTransition::AllChildrenStopped,
        );
        assert_eq!(next, Some(ActorLifecycleState::Stopped));
    }

    // --- Liar Check: Terminal states reject ALL transitions ---
    #[test]
    fn given_terminal_when_any_transition_then_none() {
        let terminals = [ActorLifecycleState::Stopped, ActorLifecycleState::Failed];
        let transitions = [
            LifecycleTransition::Start,
            LifecycleTransition::Stop,
            LifecycleTransition::ChildStopped,
            LifecycleTransition::AllChildrenStopped,
            LifecycleTransition::Fail,
        ];
        for state in &terminals {
            for trans in &transitions {
                assert_eq!(
                    compute_next_state(*state, *trans),
                    None,
                    "Terminal {:?} must reject {:?}",
                    state,
                    trans
                );
            }
        }
    }

    // --- Claim: is_terminal is true only for Stopped and Failed ---
    #[test]
    fn is_terminal_classifies_correctly() {
        assert!(!ActorLifecycleState::Pending.is_terminal());
        assert!(!ActorLifecycleState::Running.is_terminal());
        assert!(!ActorLifecycleState::Stopping.is_terminal());
        assert!(ActorLifecycleState::Stopped.is_terminal());
        assert!(ActorLifecycleState::Failed.is_terminal());
    }

    // --- Claim: is_stopping is true for Stopping and Stopped ---
    #[test]
    fn is_stopping_classifies_correctly() {
        assert!(!ActorLifecycleState::Pending.is_stopping());
        assert!(!ActorLifecycleState::Running.is_stopping());
        assert!(ActorLifecycleState::Stopping.is_stopping());
        assert!(ActorLifecycleState::Stopped.is_stopping());
        assert!(!ActorLifecycleState::Failed.is_stopping());
    }

    // --- Claim: can_spawn_child only when Pending or Running ---
    #[test]
    fn can_spawn_child_classifies_correctly() {
        assert!(ActorLifecycleState::Pending.can_spawn_child());
        assert!(ActorLifecycleState::Running.can_spawn_child());
        assert!(!ActorLifecycleState::Stopping.can_spawn_child());
        assert!(!ActorLifecycleState::Stopped.can_spawn_child());
        assert!(!ActorLifecycleState::Failed.can_spawn_child());
    }

    // --- Claim: valid_transitions matches compute_next_state ---
    #[test]
    fn valid_transitions_matches_compute() {
        for state in [
            ActorLifecycleState::Pending,
            ActorLifecycleState::Running,
            ActorLifecycleState::Stopping,
            ActorLifecycleState::Stopped,
            ActorLifecycleState::Failed,
        ] {
            let valid = state.valid_transitions();
            for trans in valid {
                assert!(
                    is_valid_transition(state, trans),
                    "valid_transitions claims {:?} is valid from {:?} but is_valid_transition disagrees",
                    trans, state
                );
            }
        }
    }

    // --- Claim: Display outputs lowercase strings ---
    #[test]
    fn display_outputs_lowercase() {
        assert_eq!(format!("{}", ActorLifecycleState::Pending), "pending");
        assert_eq!(format!("{}", ActorLifecycleState::Running), "running");
        assert_eq!(format!("{}", ActorLifecycleState::Stopping), "stopping");
        assert_eq!(format!("{}", ActorLifecycleState::Stopped), "stopped");
        assert_eq!(format!("{}", ActorLifecycleState::Failed), "failed");
    }

    // --- Breakage Check: Invalid transitions return None ---
    #[test]
    fn given_pending_when_stop_then_none() {
        assert_eq!(
            compute_next_state(ActorLifecycleState::Pending, LifecycleTransition::Stop),
            None
        );
    }

    #[test]
    fn given_running_when_start_then_none() {
        assert_eq!(
            compute_next_state(ActorLifecycleState::Running, LifecycleTransition::Start),
            None
        );
    }

    #[test]
    fn given_stopping_when_fail_then_none() {
        assert_eq!(
            compute_next_state(ActorLifecycleState::Stopping, LifecycleTransition::Fail),
            None
        );
    }
}

