mod bdd_parent_child_registry {
    use super::*;

    #[tokio::test]
    async fn given_empty_registry_when_add_child_then_child_exists() {
        let reg = ParentChildRegistry::new();
        let id = default_iid();
        reg.add_child(id.clone()).await;
        let children = reg.get_children().await;
        assert!(children.contains_key(&id));
        assert_eq!(children[&id].state, ActorLifecycleState::Pending);
    }

    #[tokio::test]
    async fn given_child_exists_when_remove_then_child_gone() {
        let reg = ParentChildRegistry::new();
        let id = default_iid();
        reg.add_child(id.clone()).await;
        reg.remove_child(&id).await;
        assert!(!reg.get_children().await.contains_key(&id));
    }

    #[tokio::test]
    async fn given_child_when_update_state_then_state_changed() {
        let reg = ParentChildRegistry::new();
        let id = default_iid();
        reg.add_child(id.clone()).await;
        let info = reg.update_child_state(&id, ActorLifecycleState::Running).await;
        assert_eq!(info.unwrap().state, ActorLifecycleState::Running);
    }

    #[tokio::test]
    async fn given_two_children_when_filter_by_state_then_correct_subset() {
        let reg = ParentChildRegistry::new();
        let id1 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let id2 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMB");
        reg.add_child(id1.clone()).await;
        reg.add_child(id2.clone()).await;
        reg.update_child_state(&id1, ActorLifecycleState::Running).await;

        let running = reg.get_children_by_state(ActorLifecycleState::Running).await;
        assert_eq!(running, vec![id1]);
        let pending = reg.get_children_by_state(ActorLifecycleState::Pending).await;
        assert_eq!(pending, vec![id2]);
    }

    #[tokio::test]
    async fn given_mixed_states_when_all_terminal_then_true_only_if_all_terminal() {
        let reg = ParentChildRegistry::new();
        let id1 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let id2 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMB");
        reg.add_child(id1.clone()).await;
        reg.add_child(id2.clone()).await;
        assert!(!reg.all_children_terminal().await);

        reg.update_child_state(&id1, ActorLifecycleState::Stopped).await;
        assert!(!reg.all_children_terminal().await);

        reg.update_child_state(&id2, ActorLifecycleState::Failed).await;
        assert!(reg.all_children_terminal().await);
    }

    #[tokio::test]
    async fn given_children_when_active_count_then_only_non_terminal() {
        let reg = ParentChildRegistry::new();
        let id1 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let id2 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMB");
        reg.add_child(id1.clone()).await;
        reg.add_child(id2.clone()).await;
        assert_eq!(reg.active_children_count().await, 2);

        reg.update_child_state(&id1, ActorLifecycleState::Stopped).await;
        assert_eq!(reg.active_children_count().await, 1);

        reg.update_child_state(&id2, ActorLifecycleState::Failed).await;
        assert_eq!(reg.active_children_count().await, 0);
    }
}

