mod bdd_reserved_permit_budget {
    use super::*;

    #[test]
    fn given_budget_when_acquire_then_available_decreases() {
        let mut budget = ReservedPermitBudget::new(3);
        assert_eq!(budget.available(WorkloadClass::Recovery), 3);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        assert_eq!(budget.available(WorkloadClass::Recovery), 2);
    }

    #[test]
    fn given_exhausted_budget_when_acquire_then_budget_exhaustion_error() {
        let mut budget = ReservedPermitBudget::new(1);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        let err = budget.try_acquire(WorkloadClass::Recovery).unwrap_err();
        assert!(matches!(err, StartError::BudgetExhaustion { class: WorkloadClass::Recovery, .. }));
    }

    #[test]
    fn given_one_acquired_when_release_then_available_increases() {
        let mut budget = ReservedPermitBudget::new(2);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        budget.release(WorkloadClass::Recovery);
        assert_eq!(budget.available(WorkloadClass::Recovery), 2);
    }

    // --- Breakage Check: release at zero is a no-op ---
    #[test]
    fn given_no_acquires_when_release_then_noop() {
        let mut budget = ReservedPermitBudget::new(5);
        budget.release(WorkloadClass::Recovery);
        assert_eq!(budget.available(WorkloadClass::Recovery), 5);
    }

    // --- Claim: Classes are independent ---
    #[test]
    fn given_exhausted_recovery_when_acquire_internal_then_succeeds() {
        let mut budget = ReservedPermitBudget::new(1);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        assert!(budget.try_acquire(WorkloadClass::Recovery).is_err());
        assert!(budget.try_acquire(WorkloadClass::Internal).is_ok());
    }

    #[test]
    fn given_budget_when_reset_then_all_available() {
        let mut budget = ReservedPermitBudget::new(5);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        budget.try_acquire(WorkloadClass::NewInstance).unwrap();
        budget.reset();
        assert_eq!(budget.available(WorkloadClass::Recovery), 5);
        assert_eq!(budget.available(WorkloadClass::NewInstance), 5);
    }

    #[test]
    fn given_new_budget_when_is_exhausted_then_false() {
        let budget = ReservedPermitBudget::new(5);
        assert!(!budget.is_exhausted(WorkloadClass::Recovery));
    }

    #[test]
    fn given_full_budget_when_is_exhausted_then_true() {
        let mut budget = ReservedPermitBudget::new(1);
        budget.try_acquire(WorkloadClass::Recovery).unwrap();
        assert!(budget.is_exhausted(WorkloadClass::Recovery));
    }
}

