mod bdd_signal_buffer {
    use super::*;

    fn make_signal(id: &str) -> BufferedSignal {
        BufferedSignal::new(
            id.to_string(),
            SignalPayload::empty(),
            TimestampMs::now(),
        )
    }

    // --- Claim: Reject policy always rejects ---
    #[test]
    fn given_reject_policy_when_no_matching_wait_then_rejected() {
        let (delivery, result) = apply_policy(BufferPolicy::Reject, false, false);
        assert_eq!(delivery, SignalDelivery::Rejected);
        assert_eq!(result, Some(BufferResult::Rejected));
    }

    // --- Claim: BufferOne rejects second signal ---
    #[test]
    fn given_buffer_one_when_existing_buffer_then_rejected() {
        let (delivery, result) = apply_policy(BufferPolicy::BufferOne, false, true);
        assert_eq!(delivery, SignalDelivery::Rejected);
        assert_eq!(result, Some(BufferResult::Rejected));
    }

    // --- Claim: BufferOne accepts first signal ---
    #[test]
    fn given_buffer_one_when_no_existing_then_buffered() {
        let (delivery, result) = apply_policy(BufferPolicy::BufferOne, false, false);
        assert_eq!(delivery, SignalDelivery::Buffered);
        assert_eq!(result, Some(BufferResult::Buffered));
    }

    // --- Claim: Matching wait always accepts ---
    #[test]
    fn given_matching_wait_when_any_policy_then_accepted() {
        for policy in [BufferPolicy::Reject, BufferPolicy::BufferOne, BufferPolicy::BufferMany] {
            let (delivery, _) = apply_policy(policy, true, false);
            assert_eq!(delivery, SignalDelivery::Accepted);
        }
    }

    // --- Claim: BufferMany buffers multiple ---
    #[test]
    fn given_buffer_many_when_buffer_signal_then_multiple_stored() {
        let mut buf = SignalBuffer::new(SignalBufferConfig::new(5));
        let id = default_iid();
        let wk = WaitKey::parse("test-key").unwrap();

        assert_eq!(
            buf.buffer_signal(id.clone(), wk.clone(), make_signal("s1"), BufferPolicy::BufferMany),
            BufferResult::Buffered
        );
        assert_eq!(
            buf.buffer_signal(id.clone(), wk.clone(), make_signal("s2"), BufferPolicy::BufferMany),
            BufferResult::Buffered
        );
        assert_eq!(buf.buffered_count(&id, &wk), 2);
    }

    // --- Claim: BufferMany drops when full ---
    #[test]
    fn given_buffer_many_when_full_then_drops() {
        let mut buf = SignalBuffer::new(SignalBufferConfig::new(2));
        let id = default_iid();
        let wk = WaitKey::parse("test-key").unwrap();

        buf.buffer_signal(id.clone(), wk.clone(), make_signal("s1"), BufferPolicy::BufferMany);
        buf.buffer_signal(id.clone(), wk.clone(), make_signal("s2"), BufferPolicy::BufferMany);
        assert_eq!(
            buf.buffer_signal(id.clone(), wk.clone(), make_signal("s3"), BufferPolicy::BufferMany),
            BufferResult::Dropped
        );
    }

    // --- Claim: pop_buffered returns FIFO order ---
    #[test]
    fn given_buffered_when_pop_then_fifo_order() {
        let mut buf = SignalBuffer::new(SignalBufferConfig::new(10));
        let id = default_iid();
        let wk = WaitKey::parse("test-key").unwrap();

        buf.buffer_signal(id.clone(), wk.clone(), make_signal("first"), BufferPolicy::BufferMany);
        buf.buffer_signal(id.clone(), wk.clone(), make_signal("second"), BufferPolicy::BufferMany);

        let first = buf.pop_buffered(&id, &wk).unwrap();
        assert_eq!(first.signal_id, "first");
        let second = buf.pop_buffered(&id, &wk).unwrap();
        assert_eq!(second.signal_id, "second");
        assert!(buf.pop_buffered(&id, &wk).is_none());
    }

    // --- Claim: clear removes all signals for key ---
    #[test]
    fn given_buffered_when_clear_then_empty() {
        let mut buf = SignalBuffer::new(SignalBufferConfig::new(10));
        let id = default_iid();
        let wk = WaitKey::parse("test-key").unwrap();

        buf.buffer_signal(id.clone(), wk.clone(), make_signal("s1"), BufferPolicy::BufferMany);
        buf.clear(&id, &wk);
        assert_eq!(buf.buffered_count(&id, &wk), 0);
    }

    // --- Claim: total_buffered_count and num_keys_with_signals ---
    #[test]
    fn given_multiple_keys_when_count_then_correct_totals() {
        let mut buf = SignalBuffer::new(SignalBufferConfig::new(10));
        let id1 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let id2 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMB");
        let wk = WaitKey::parse("key").unwrap();

        buf.buffer_signal(id1, wk.clone(), make_signal("s1"), BufferPolicy::BufferMany);
        buf.buffer_signal(id2, wk, make_signal("s2"), BufferPolicy::BufferMany);

        assert_eq!(buf.num_keys_with_signals(), 2);
        assert_eq!(buf.total_buffered_count(), 2);
    }

    // --- Claim: can_buffer rejects for Reject policy ---
    #[test]
    fn given_reject_policy_when_can_buffer_then_false() {
        let config = SignalBufferConfig::default();
        assert!(!can_buffer(BufferPolicy::Reject, false, 0, &config));
    }
}

