mod bdd_control_actor {
    use super::*;

    // --- Cancel success path ---
    #[test]
    fn given_running_instance_when_cancel_then_events_emitted() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let (cancel_req, workflow_cancelled) = actor.handle_cancel(id.clone()).unwrap();
        assert_eq!(cancel_req.instance_id, id);
        assert_eq!(workflow_cancelled.instance_id, id);
        assert!(workflow_cancelled.cancelled_at >= cancel_req.requested_at);
    }

    // --- Cancel on terminal: AlreadyTerminal ---
    #[test]
    fn given_completed_instance_when_cancel_then_already_terminal() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9B00C000"); // Completed
        match actor.handle_cancel(id.clone()) {
            Err(CancelError::AlreadyTerminal { current_state: LifecycleState::Completed, .. }) => {}
            other => panic!("Expected AlreadyTerminal(Completed), got {:?}", other),
        }
    }

    // --- Cancel on cancelled: AlreadyTerminal ---
    #[test]
    fn given_cancelled_instance_when_cancel_then_already_terminal() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9B00X000"); // Cancelled
        match actor.handle_cancel(id.clone()) {
            Err(CancelError::AlreadyTerminal { current_state: LifecycleState::Cancelled, .. }) => {}
            other => panic!("Expected AlreadyTerminal(Cancelled), got {:?}", other),
        }
    }

    // --- Cancel non-existent: InstanceActorNotFound ---
    #[test]
    fn given_nonexistent_instance_when_cancel_then_not_found() {
        let actor = ControlActor::new();
        let id = iid("00000000000000000000000001");
        match actor.handle_cancel(id) {
            Err(CancelError::InstanceActorNotFound { .. }) => {}
            other => panic!("Expected InstanceActorNotFound, got {:?}", other),
        }
    }

    // --- Cancel lock failure ---
    #[test]
    fn given_lock_error_when_cancel_then_lock_failed() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9BA00000"); // 'A' = lock error
        match actor.handle_cancel(id) {
            Err(CancelError::LockAcquisitionFailed { .. }) => {}
            other => panic!("Expected LockAcquisitionFailed, got {:?}", other),
        }
    }

    // --- Cancel storage failure ---
    #[test]
    fn given_storage_error_when_cancel_then_storage_error() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9BS00000"); // 'S' = storage error
        match actor.handle_cancel(id) {
            Err(CancelError::StorageError { .. }) => {}
            other => panic!("Expected StorageError, got {:?}", other),
        }
    }

    // --- Resume success path ---
    #[test]
    fn given_failed_instance_when_resume_then_instance_resumed() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9B00F000"); // Failed
        let resumed = actor.handle_resume(id.clone()).unwrap();
        assert_eq!(resumed.instance_id, id);
        assert_ne!(resumed.previous_binary_hash, resumed.resumed_binary_hash);
    }

    // --- Resume non-failed: InvalidLifecycleState ---
    #[test]
    fn given_running_instance_when_resume_then_invalid_state() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9B000000"); // Running
        match actor.handle_resume(id) {
            Err(ResumeError::InvalidLifecycleState { actual: LifecycleState::Running, expected: LifecycleState::Failed }) => {}
            other => panic!("Expected InvalidLifecycleState, got {:?}", other),
        }
    }

    // --- Resume error taxonomy: all precondition errors ---
    #[test]
    fn given_resume_errors_when_classify_then_preconditions_correct() {
        let id = default_iid();
        let precondition: Vec<ResumeError> = vec![
            ResumeError::InvalidLifecycleState { actual: LifecycleState::Running, expected: LifecycleState::Failed },
            ResumeError::MissingSecrets { instance_id: id.clone(), missing_secret_ids: vec![SecretId::new("s1")] },
            ResumeError::NodeNotFound { instance_id: id.clone(), node_name: NodeName::new("n1") },
            ResumeError::NoPathToTerminal { instance_id: id.clone(), current_node: NodeName::new("n2") },
            ResumeError::InstanceActorNotFound { instance_id: id.clone() },
        ];
        for err in &precondition {
            assert!(err.is_precondition(), "Expected {:?} to be precondition", err);
            assert!(!err.is_transient(), "Expected {:?} to NOT be transient", err);
        }

        let transient: Vec<ResumeError> = vec![
            ResumeError::LockAcquisitionFailed { instance_id: id.clone(), reason: "locked".to_string() },
            ResumeError::StorageError { instance_id: id, reason: "io".to_string() },
        ];
        for err in &transient {
            assert!(!err.is_precondition(), "Expected {:?} to NOT be precondition", err);
            assert!(err.is_transient(), "Expected {:?} to be transient", err);
        }
    }

    // --- AcceptResume success ---
    #[test]
    fn given_waiting_for_signal_when_accept_and_resume_then_outcome() {
        let actor = ControlActor::new();
        let id = iid("01H5JYV4XHGSR2F8KZ9B00W000"); // WaitingForSignal
        let wk = WaitKey::parse("approval").unwrap();
        let outcome = actor.accept_and_resume(id.clone(), wk, "sig-1".to_string(), SignalPayload::empty()).unwrap();
        assert_eq!(outcome.accepted.instance_id, id);
        assert_eq!(outcome.resumed.instance_id, id);
    }

    // --- AcceptResume error classification ---
    #[test]
    fn given_accept_resume_errors_when_classify_then_correct() {
        let id = default_iid();
        let precondition: Vec<AcceptResumeError> = vec![
            AcceptResumeError::InvalidLifecycleState { instance_id: id.clone(), actual: LifecycleState::Running, expected: LifecycleState::WaitingForSignal },
            AcceptResumeError::WaitKeyMismatch { instance_id: id.clone(), expected_key: WaitKey::new_unchecked("a"), provided_key: WaitKey::new_unchecked("b") },
            AcceptResumeError::InstanceActorNotFound { instance_id: id.clone() },
            AcceptResumeError::PayloadTooLarge { instance_id: id, payload_size: 65537, max_size: 65536 },
        ];
        for err in &precondition {
            assert!(err.is_precondition());
            assert!(!err.is_transient());
        }
    }
}

// ============================================================================
// MODULE 9: InstanceRegistry (single-active guarantee)
// ============================================================================

mod bdd_instance_registry {
    use super::*;

    #[test]
    fn given_empty_registry_when_register_then_active() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id = default_iid();
        reg.register(id.clone(), InstanceActorHandle::test(1), |_h| Ok(())).unwrap();
        assert!(reg.is_active(&id));
        assert_eq!(reg.active_count(), 1);
    }

    #[test]
    fn given_active_when_register_same_id_then_stop_before_replace() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id = default_iid();
        reg.register(id.clone(), InstanceActorHandle::test(1), |_h| Ok(())).unwrap();

        // Re-register with new handle — prior should be stopped
        reg.register(id.clone(), InstanceActorHandle::test(2), |_h| Ok(())).unwrap();
        assert!(reg.is_active(&id));
        let handle = reg.lookup(&id).unwrap();
        assert_eq!(handle.handle_id(), 2); // New handle replaced old
    }

    #[test]
    fn given_active_when_register_and_stop_fails_then_old_preserved() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id = default_iid();
        reg.register(id.clone(), InstanceActorHandle::test(1), |_h| Ok(())).unwrap();

        // Try to re-register but stop_fn fails
        let result = reg.register(id.clone(), InstanceActorHandle::test(2), |_h| Err("stop failed".to_string()));
        assert!(result.is_err());
        // INV-5: Old handle preserved
        let handle = reg.lookup(&id).unwrap();
        assert_eq!(handle.handle_id(), 1);
    }

    #[test]
    fn given_active_when_deregister_then_removed() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id = default_iid();
        reg.register(id.clone(), InstanceActorHandle::test(1), |_h| Ok(())).unwrap();
        let handle = reg.deregister(&id).unwrap();
        assert_eq!(handle.handle_id(), 1);
        assert!(!reg.is_active(&id));
    }

    #[test]
    fn given_not_registered_when_deregister_then_not_registered_error() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id = default_iid();
        let result = reg.deregister(&id);
        assert!(matches!(result, Err(RegistryError::NotRegistered { .. })));
    }

    // --- INV-3: Count consistency ---
    #[test]
    fn given_multiple_registrations_when_count_then_consistent() {
        let mut reg = InstanceRegistry::new(RegistryConfig::default());
        let id1 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMA");
        let id2 = iid("01H5JYV4XHGSR2F8KZ9BWNRFMB");

        reg.register(id1, InstanceActorHandle::test(1), |_h| Ok(())).unwrap();
        reg.register(id2, InstanceActorHandle::test(2), |_h| Ok(())).unwrap();
        assert_eq!(reg.active_count(), 2);

        reg.deregister(&iid("01H5JYV4XHGSR2F8KZ9BWNRFMA")).unwrap();
        assert_eq!(reg.active_count(), 1);
    }
}

