// ============================================================================

mod bdd_spawn_supervisor_calc {
    use super::*;

    #[test]
    fn given_first_attempt_when_backoff_then_initial() {
        assert_eq!(calculate_backoff_delay(1000, 2.0, 1), 1000);
    }

    #[test]
    fn given_later_attempt_when_backoff_then_exponential() {
        assert_eq!(calculate_backoff_delay(1000, 2.0, 2), 2000);
        assert_eq!(calculate_backoff_delay(1000, 2.0, 3), 4000);
    }

    #[test]
    fn given_multiplier_1_when_backoff_then_constant() {
        assert_eq!(calculate_backoff_delay(1000, 1.0, 1), 1000);
        assert_eq!(calculate_backoff_delay(1000, 1.0, 10), 1000);
    }

    #[test]
    fn given_failed_high_attempts_when_is_zombie_then_true() {
        let record = SpawnRecord {
            spawn_id: None,
            instance_id: default_iid(),
            command: "test".to_string(),
            spawn_phase: SpawnPhase::Failed,
            health_checks: 0,
            spawn_attempts: 5,
            last_error: None,
        };
        assert!(is_zombie_state(&record));
    }

    #[test]
    fn given_failed_low_attempts_when_is_zombie_then_false() {
        let record = SpawnRecord {
            spawn_id: None,
            instance_id: default_iid(),
            command: "test".to_string(),
            spawn_phase: SpawnPhase::Failed,
            health_checks: 0,
            spawn_attempts: 2,
            last_error: None,
        };
        assert!(!is_zombie_state(&record));
    }

    #[test]
    fn given_failed_within_limit_when_should_respawn_then_true() {
        let record = SpawnRecord {
            spawn_id: None,
            instance_id: default_iid(),
            command: "test".to_string(),
            spawn_phase: SpawnPhase::Failed,
            health_checks: 0,
            spawn_attempts: 2,
            last_error: None,
        };
        assert!(should_respawn(&record, 5));
    }

    #[test]
    fn given_failed_at_limit_when_should_respawn_then_false() {
        let record = SpawnRecord {
            spawn_id: None,
            instance_id: default_iid(),
            command: "test".to_string(),
            spawn_phase: SpawnPhase::Failed,
            health_checks: 0,
            spawn_attempts: 5,
            last_error: None,
        };
        assert!(!should_respawn(&record, 5));
    }

    // --- Claim: SpawnRecord transitions are pure (return new, don't mutate) ---
    #[test]
    fn given_record_when_transition_then_original_unchanged() {
        let original = SpawnRecord::new(default_iid(), "cmd".to_string(), None);
        let _health = original.transition_to_health_check();
        assert_eq!(original.spawn_phase, SpawnPhase::Spawn); // original unchanged
    }

    // --- Claim: respawn increments attempts ---
    #[test]
    fn given_record_when_respawn_then_attempts_incremented() {
        let record = SpawnRecord {
            spawn_id: None,
            instance_id: default_iid(),
            command: "test".to_string(),
            spawn_phase: SpawnPhase::Failed,
            health_checks: 0,
            spawn_attempts: 3,
            last_error: None,
        };
        let respawned = record.respawn(None);
        assert_eq!(respawned.spawn_attempts, 4);
        assert_eq!(respawned.spawn_phase, SpawnPhase::Spawn);
        assert_eq!(respawned.health_checks, 0);
    }

    // --- Error taxonomy claims ---
    #[test]
    fn given_errors_when_classify_then_correct_categories() {
        let transient = SpawnSupervisorError::StorageError("x".to_string());
        let resumable = SpawnSupervisorError::HealthCheckFailed {
            instance_id: default_iid(),
            check_number: 1,
            error: "fail".to_string(),
        };
        let fatal = SpawnSupervisorError::CorruptSpawn("bad".to_string());
        let operational = SpawnSupervisorError::AlreadyRunning;

        assert!(transient.is_transient());
        assert!(!transient.is_resumable());
        assert!(resumable.is_resumable());
        assert!(!resumable.is_fatal());
        assert!(fatal.is_fatal());
        assert!(!fatal.is_operational());
        assert!(operational.is_operational());
    }
}

