mod bdd_message_router {
    use super::*;

    #[test]
    fn given_empty_router_when_register_channel_then_has_channel() {
        let mut router = MessageRouter::with_default_config();
        let ch = ChannelId::new("test");
        router.register_channel(ch.clone(), ActorDestination::new("actor")).unwrap();
        assert!(router.has_channel(&ch));
        assert_eq!(router.num_channels(), 1);
    }

    #[test]
    fn given_existing_channel_when_register_same_then_error() {
        let mut router = MessageRouter::with_default_config();
        let ch = ChannelId::new("test");
        router.register_channel(ch.clone(), ActorDestination::new("a1")).unwrap();
        let result = router.register_channel(ch.clone(), ActorDestination::new("a2"));
        assert!(matches!(result, Err(RouteError::ChannelAlreadyExists(_))));
    }

    #[test]
    fn given_channel_when_unregister_then_removed() {
        let mut router = MessageRouter::with_default_config();
        let ch = ChannelId::new("test");
        router.register_channel(ch.clone(), ActorDestination::new("a1")).unwrap();
        router.unregister_channel(&ch);
        assert!(!router.has_channel(&ch));
    }

    #[test]
    fn given_channel_when_deactivate_then_no_active_destinations() {
        let mut router = MessageRouter::with_default_config();
        let ch = ChannelId::new("test");
        router.register_channel(ch.clone(), ActorDestination::new("a1")).unwrap();
        router.deactivate_channel(&ch).unwrap();
        assert!(!router.is_channel_active(&ch));
    }

    #[test]
    fn given_full_dlq_when_enqueue_then_fifo_eviction() {
        let mut dlq = DeadLetterQueue::new(2);
        for i in 0..4 {
            dlq.enqueue(DeadLetterEntry {
                channel_id: ChannelId::new(format!("ch-{}", i)),
                message: DeadLetterMessage { payload: vec![], type_name: "test".to_string() },
                enqueued_at: TimestampMs::now(),
                reason: DeadLetterReason::ChannelNotFound,
            });
        }
        assert_eq!(dlq.len(), 2);
        let ids: Vec<&str> = dlq.entries.iter().map(|e| e.channel_id.as_str()).collect();
        assert!(ids.contains(&"ch-2"));
        assert!(ids.contains(&"ch-3"));
        assert!(!ids.contains(&"ch-0"));
    }

    // --- ChannelId validation ---
    #[test]
    fn given_empty_string_when_channel_id_parse_then_err() {
        assert!(ChannelId::parse("").is_err());
    }

    #[test]
    fn given_non_empty_when_channel_id_then_ok() {
        let id = ChannelId::new("my-channel");
        assert_eq!(id.as_str(), "my-channel");
    }
}

