mod bdd_error_display {
    use super::*;

    #[test]
    fn given_lifecycle_error_when_display_then_human_readable() {
        let err = LifecycleError::InvalidTransition {
            from: ActorLifecycleState::Running,
            attempted: LifecycleTransition::Start,
        };
        assert!(format!("{}", err).contains("invalid transition"));

        let err = LifecycleError::ChildNotFound(default_iid());
        assert!(format!("{}", err).contains("child not found"));

        let err = LifecycleError::CannotSpawnChild(ActorLifecycleState::Stopped);
        assert!(format!("{}", err).contains("cannot spawn child"));

        let err = LifecycleError::ShutdownTimeout { children_remaining: 3 };
        assert!(format!("{}", err).contains("shutdown timeout"));
    }

    #[test]
    fn given_start_error_when_display_then_contains_class() {
        let err = StartError::BudgetExhaustion {
            class: WorkloadClass::Recovery,
            requested: 1,
            available: 0,
        };
        let msg = format!("{}", err);
        assert!(msg.contains("Recovery"));
        assert!(msg.contains("requested"));
        assert!(msg.contains("available"));
    }

    #[test]
    fn given_registry_error_when_display_then_contextual() {
        let err = RegistryError::StopFailed {
            instance_id: default_iid(),
            reason: "timeout".to_string(),
        };
        assert!(format!("{}", err).contains("stop failed"));

        let err = RegistryError::StopTimeout {
            instance_id: default_iid(),
            timeout: Duration::from_secs(5),
        };
        assert!(format!("{}", err).contains("stop timeout"));

        let err = RegistryError::NotRegistered { instance_id: default_iid() };
        assert!(format!("{}", err).contains("not registered"));
    }
}
